from pathlib import Path
p=Path('src/main/java/org/slavicmyths/furniture/SeatEntity.java');s=p.read_text(encoding='utf-8').replace('seat.remove()','seat.discard()').replace('ejectPassengers();remove();','ejectPassengers();discard();').replace('@Override public double getPassengersRidingOffset(){return .05;}','@Override public Vec3 getPassengerRidingPosition(Entity passenger){return position().add(0,.05,0);}') .replace('.getMaterial().isSolid()','.isSolid()');p.write_text(s,encoding='utf-8')
p=Path('src/main/java/org/slavicmyths/flight/FlyingVessel.java');s=p.read_text(encoding='utf-8').replace('public Entity getControllingPassenger()','public LivingEntity getControllingPassenger()').replace('repack(p);remove();if(!p.inventory.add(result))','repack(p);discard();if(!p.getInventory().add(result))').replace('causeFallDamage(float d,float multiplier)','causeFallDamage(float d,float multiplier,DamageSource source)').replace('@Override public double getPassengersRidingOffset(){return mortar?.65:0;}','@Override public Vec3 getPassengerRidingPosition(Entity rider){return position().add(0,mortar?.65:0,0);}') .replace('@Override public void positionRider(Entity rider){if(hasPassenger(rider)){rider.setPos(getX(),getY()+getPassengersRidingOffset()+rider.getMyRidingOffset(),getZ());rider.fallDistance=0;}}','@Override protected void positionRider(Entity rider,Entity.MoveFunction move){super.positionRider(rider,move);rider.fallDistance=0;}').replace('.getMaterial().isSolid()','.isSolid()').replace('yRot+=Mth.wrapDegrees(targetYaw-yRot)/lerpSteps;','setYRot(getYRot()+Mth.wrapDegrees(targetYaw-getYRot())/lerpSteps);').replace('wantedYaw-yRot','wantedYaw-getYRot()').replace('yRot+=turn','setYRot(getYRot()+turn)').replace('new BlockPos(getX()+vx,getY(),getZ()+vz)','BlockPos.containing(getX()+vx,getY(),getZ()+vz)').replace('isOnGround()','onGround()').replace('int steps,boolean teleport','int steps');p.write_text(s,encoding='utf-8')
